// Exact necessary coverage check for r9/a7/III union size21. Unfixed matching deletions are minimized after choosing S. No SAT.
// Input: the existing complete brown57.edges. See BROWN_R9_SEVEN_III_OBSTRUCTION.md.
#include <bits/stdc++.h>
using namespace std;using U=uint64_t;int pc(U x){return __builtin_popcountll(x);}int lo(U x){return __builtin_ctzll(x);}const U ALL=(1ULL<<57)-1;
int main(int argc,char**argv){ifstream f(argv[1]);int n,m;f>>n>>m;U a[57]={},C=0,I=0,E;vector<pair<int,int>>ed;for(int u,v;f>>u>>v;){a[u]|=1ULL<<v;a[v]|=1ULL<<u;ed.push_back({u,v});}for(int v=0;v<57;v++)if(pc(a[v])==7)C|=1ULL<<v;for(int v=0;v<57;v++)if(!(C>>v&1)&&!(a[v]&C))I|=1ULL<<v;E=ALL^C^I;vector<U>T;for(auto[u,v]:ed)if((I>>u&1)&&(I>>v&1))for(int w=v+1;w<57;w++)if((I>>w&1)&&(a[u]>>w&1)&&(a[v]>>w&1))T.push_back((1ULL<<u)|(1ULL<<v)|(1ULL<<w));long long nodes=0,passes=0,cases=0;int fam=0;bool stop=false;array<int,7>ix;map<string,long long>typecases,typepasses;
auto typ=[&](pair<int,int>e){int u=e.first,v=e.second;if((I>>u&1)&&(I>>v&1))return string("II");if((C>>u&1)||(C>>v&1))return string("CE");if((I>>u&1)||(I>>v&1))return string("IE");return string("EE");};
function<void(int,int)>outer=[&](int k,int st){if(stop)return;if(k<7){for(int q=st;q<=14-(7-k);q++){ix[k]=q;outer(k+1,q+1);}return;}U uni=0;for(int q:ix)uni|=T[q];if(pc(uni)!=21)return;fam++;vector<U>base;for(int q:ix)base.push_back(T[q]);vector<pair<int,int>>extras;for(auto e:ed){U em=(1ULL<<e.first)|(1ULL<<e.second);if((em&I)!=em||any_of(base.begin(),base.end(),[&](U t){return (t&em)==em;}))extras.push_back(e);}assert(extras.size()==203);
for(int p=0;p<(int)extras.size()&&!stop;p++)for(int q=p+1;q<(int)extras.size()&&!stop;q++){auto e1=extras[p],e2=extras[q];U endpoints=(1ULL<<e1.first)|(1ULL<<e1.second)|(1ULL<<e2.first)|(1ULL<<e2.second);vector<U>affected,groups;for(U t:base)if(t&endpoints)affected.push_back(t);else groups.push_back(t);assert(affected.size()<=2);vector<pair<int,int>>known{e1,e2};string tt=typ(e1)+"+"+typ(e2);
function<void(int)>fixed=[&](int dep){if(stop)return;if(dep<(int)affected.size()){U t=affected[dep];for(auto e:ed)if(e!=e1&&e!=e2&&(t>>e.first&1)&&(t>>e.second&1)){known.push_back(e);fixed(dep+1);known.pop_back();}return;}cases++;typecases[tt]++;U allowed=C,cov[57];int d[57]={},weight[57]={},gid[57];fill(gid,gid+57,-1);for(int v=0;v<57;v++)cov[v]=a[v]|(1ULL<<v);for(auto[u,v]:known){d[u]++;d[v]++;cov[u]&=~(1ULL<<v);cov[v]&=~(1ULL<<u);}int maxmiss=0;for(int v=0;v<57;v++){if(d[v])allowed|=1ULL<<v;if(d[v]||(C>>v&1)){weight[v]=d[v]+(C>>v&1)-1;maxmiss+=weight[v];}}assert(maxmiss<=3);for(int g=0;g<(int)groups.size();g++){assert(!(allowed&groups[g]));allowed|=groups[g];for(U z=groups[g];z;z&=z-1)gid[lo(z)]=g;}
function<void(U,U,U,U,int,int)>dfs=[&](U S,U avail,U covered,U ignored,int depth,int sigma){if(stop)return;nodes++;if(depth==8){int need=pc(ALL&~covered);if(need>sigma)return;for(U g:groups){U sg=S&g;if(pc(sg)!=1)continue;int v=lo(sg);bool safe=false;for(U partners=g&~sg;partners;partners&=partners-1){int w=lo(partners);if(pc(a[w]&S)>=2){safe=true;break;}}if(!safe)need++;}if(need<=sigma){passes++;typepasses[tt]++;cout<<"PASS family="<<fam<<" case="<<cases<<" type="<<tt<<" S="<<S<<" initial_uncovered="<<(ALL&~covered)<<" need="<<need<<" sigma="<<sigma<<" known=";for(auto[u,v]:known)cout<<u<<","<<v<<";";cout<<"\n"<<flush;if(passes>=10)stop=true;}return;}if(pc(avail)<8-depth)return;U unc=ALL&~covered&~ignored;int budget=maxmiss-pc(ignored);vector<int>gains;for(U z=avail;z;z&=z-1)gains.push_back(pc(cov[lo(z)]&unc));sort(gains.rbegin(),gains.rend());int upper=budget;for(int j=0;j<8-depth;j++)upper+=gains[j];if(upper<pc(unc))return;U choices=avail;if(unc){int best=58,target=-1;for(U z=unc;z;z&=z-1){int u=lo(z);U poss=0;for(U zz=avail;zz;zz&=zz-1){int v=lo(zz);if(cov[v]>>u&1)poss|=1ULL<<v;}if(pc(poss)<best){best=pc(poss);choices=poss;target=u;if(!best)break;}}if(budget>0)dfs(S,avail,covered,ignored|(1ULL<<target),depth,sigma);}
while(choices&&!stop){int v=lo(choices);U bit=1ULL<<v;choices&=choices-1;avail&=~bit;U next=avail;int g=gid[v];if(g>=0&&S&groups[g])next&=~groups[g];dfs(S|bit,next,covered|cov[v],ignored,depth+1,sigma+weight[v]);}
};dfs(0,allowed,0,0,0,0);if(cases%1000==0)cout<<"PROGRESS cases="<<cases<<" nodes="<<nodes<<" passes="<<passes<<"\n"<<flush;
};fixed(0);} }
;outer(0,0);cout<<"TOTAL families="<<fam<<" cases="<<cases<<" nodes="<<nodes<<" passes="<<passes<<" complete="<<!stop<<"\n";for(auto[t,c]:typecases)cout<<t<<" cases="<<c<<" passes="<<typepasses[t]<<"\n";}
